package dev.dwmir.lib;
import net.fabricmc.fabric.api.client.gametest.v1.*;import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.*;import net.minecraft.client.input.MouseInput;import net.minecraft.item.*;import net.minecraft.text.Text;import dev.dwmir.countit.*;import dev.dwmir.lib.api.*;
public final class R9Checks implements FabricClientGameTest {
 private Object field(Object target,String name){try{var f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}catch(Exception e){throw new AssertionError(e);}}
 private void check(boolean b,String text){if(!b)throw new AssertionError(text);}
 private void click(MinecraftClient c,String label){Screen actual=WorkspaceScreen.actual(c.currentScreen);var button=actual.children().stream().filter(e->e instanceof ClickableWidget w&&w.getMessage().getString().startsWith(label)).map(e->(ClickableWidget)e).findFirst().orElseThrow(()->new AssertionError(label));double x=button.getX()+button.getWidth()/2.,y=button.getY()+button.getHeight()/2.;if(c.currentScreen instanceof WorkspaceScreen w){x=w.screenX(x);y=w.screenY(y);}var event=new Click(x,y,new MouseInput(0,0));check(c.currentScreen.mouseClicked(event,false),"Rejected click "+label);c.currentScreen.mouseReleased(event);}
 public void runTest(ClientGameTestContext t){
  new VanillaIconExport().runTest(t);t.getInput().resizeWindow(1440,900);t.runOnClient(c->{LibraryState.accept("library-onboarding-v2");LibraryState.select(LibraryState.Theme.SAKURA);c.options.language="en_us";c.options.getGuiScale().setValue(2);c.onResolutionChanged();check(DwmirLib.settings("countit")!=null,"Count It registration");Config.current=new Config();Config.current.volume=0;try{java.nio.file.Path imported=Config.directory().resolve("fixture.ogg");java.nio.file.Files.createDirectories(Config.directory());try(var in=c.getResourceManager().getResource(net.minecraft.util.Identifier.of("countit","sounds/custom.ogg")).orElseThrow().getInputStream()){java.nio.file.Files.copy(in,imported,java.nio.file.StandardCopyOption.REPLACE_EXISTING);}Sounds.importFile(imported.toString());var system=field(c.getSoundManager(),"soundSystem");var loader=(net.minecraft.client.sound.SoundLoader)field(system,"soundLoader");try(var stream=loader.loadStreamed(net.minecraft.util.Identifier.of("countit","sounds/custom.ogg"),false).join()){check(stream.read(4096).hasRemaining(),"Imported OGG did not decode");}Config.current.customSound=false;}catch(Exception e){throw new AssertionError(e);}for(String sound:Sounds.IDS)check(net.minecraft.registry.Registries.SOUND_EVENT.containsId(net.minecraft.util.Identifier.ofVanilla(sound)),"Unknown preset "+sound);});
  try(var world=t.worldBuilder().create()){
   world.getClientWorld().waitForChunksRender();t.runOnClient(c->{c.player.getInventory().setStack(0,new ItemStack(Items.TOTEM_OF_UNDYING));c.player.getInventory().setStack(40,new ItemStack(Items.TOTEM_OF_UNDYING));c.player.setYaw(0);c.player.setPitch(0);});
   t.setScreen(()->new dev.dwmir.countit.SettingsScreen(null));t.waitTicks(8);t.takeScreenshot("r9-countit-counter");
   t.runOnClient(c->{click(c,"Sounds");});t.waitTicks(8);t.takeScreenshot("r9-countit-sounds");
   t.runOnClient(c->click(c,"Totem"));t.waitTicks(8);t.takeScreenshot("r9-countit-totem");t.runOnClient(c->{Screen before=c.currentScreen;click(c,"Totem tint");check(c.currentScreen==before&&((WorkspaceScreen)before).hasPicker(),"Picker replaced menu");});t.waitTicks(8);t.takeScreenshot("r9-inline-picker");t.runOnClient(c->{((WorkspaceScreen)c.currentScreen).close();});
   t.runOnClient(c->click(c,"Particles"));t.waitTicks(8);t.takeScreenshot("r9-countit-particles");
   t.setScreen(()->new DemoScreen(null));t.waitTicks(8);t.takeScreenshot("r9-ten-icons");
   t.setScreen(()->Visuals.editor(null));t.runOnClient(c->{var cfg=Config.current;int x=cfg.hudX,y=cfg.hudY;var down=new Click(x+72*cfg.hudScale,y+25*cfg.hudScale,new MouseInput(0,0));check(c.currentScreen.mouseClicked(down,false),"Corner resize rejected");var move=new Click(down.x()+36,down.y()+12,new MouseInput(0,0));c.currentScreen.mouseDragged(move,36,12);c.currentScreen.mouseReleased(move);check(cfg.hudScale>1.3,"Corner did not resize");var right=new Click(x+20,y+12,new MouseInput(1,0));check(c.currentScreen.mouseClicked(right,false),"Right click rejected");});t.waitTicks(8);t.takeScreenshot("r9-hud-context");
   t.runOnClient(c->{Config.current.popX=.7f;Config.current.popY=.45f;Config.current.popScale=.65f;Config.current.totemColor=0xff88bb;Config.current.totemOpacity=.65f;CountIt.test(0);});t.waitTicks(10);t.takeScreenshot("r9-real-totem-test");
   t.setScreen(()->new net.customcrossbowsounds.client.hud.ArrowHudEditScreen(null));t.waitTicks(8);t.takeScreenshot("r9-crossbow-editor");
   for(int style=0;style<4;style++){final int st=style;t.runOnClient(c->{me.shedaniel.autoconfig.AutoConfig.getConfigHolder(net.customcrossbowsounds.config.CustomCrossbowSoundsConfig.class).getConfig().effectHudStyle=st;});t.setScreen(()->new net.customcrossbowsounds.client.SettingsScreen(null));t.runOnClient(c->((net.customcrossbowsounds.client.SettingsScreen)WorkspaceScreen.actual(c.currentScreen)).selectPage(2));t.waitTicks(8);t.takeScreenshot("r9-crossbow-style-"+style);}
   t.setScreen(()->new dev.shieldpulse.SettingsScreen(null));t.waitTicks(8);t.takeScreenshot("r9-shield-header");t.setScreen(()->dev.shieldpulse.RecoveryEditor.create(null));t.waitTicks(8);t.takeScreenshot("r9-recovery-editor");
   for(int mode=0;mode<3;mode++){final int m=mode;t.setScreen(()->DwmirLib.settings("inventoryscalefix").apply(null));if(mode>0)t.runOnClient(c->{for(int i=0;i<m;i++)click(c,"Scale mode:");});t.waitTicks(8);t.takeScreenshot("r9-inventory-mode-"+mode);}
   t.setScreen(()->new dev.dwmir.sprinter.HudEditor(null));t.waitTicks(8);t.takeScreenshot("r9-sprinter-icon");
   t.setScreen(()->null);t.runOnClient(c->{CountIt.ledger=new Ledger();var remote=new net.minecraft.client.network.OtherClientPlayerEntity(c.world,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"CountItTarget"));remote.setId(424242);remote.setPosition(c.player.getX(),c.player.getY(),c.player.getZ()+4);c.world.addEntity(remote);for(int i=0;i<3;i++){long now=CountIt.now()-1000+i*20;CountIt.ledger.damage(remote.getUuid(),true,now);CountIt.ledger.pop(remote.getUuid(),remote.getName().getString(),now);}CountIt.ledger.settle(CountIt.now());check(CountIt.ledger.count("CountItTarget")==3,"Attributed totals");check(CountIt.ledger.streak(CountIt.now())==3,"Streak threshold");CountIt.saveLedger();CountIt.ledger=new Ledger();CountIt.loadLedger();check(CountIt.ledger.count("CountItTarget")==3,"Persistent counts");c.getNetworkHandler().onEntityStatus(new net.minecraft.network.packet.s2c.play.EntityStatusS2CPacket(remote,(byte)35));check(CountIt.ledger.visible(remote.getUuid())==1,"Network pop hook");c.getNetworkHandler().onEntityDamage(new net.minecraft.network.packet.s2c.play.EntityDamageS2CPacket(remote,c.world.getDamageSources().playerAttack(c.player)));});t.waitTicks(8);t.takeScreenshot("r9-world-counter");
   t.runOnClient(c->{CountIt.ledger.resetVisible();java.util.UUID id=java.util.UUID.randomUUID();for(int i=0;i<3;i++){long n=CountIt.now()-600+i*20;CountIt.ledger.damage(id,true,n);CountIt.ledger.pop(id,"StreakTarget",n);}CountIt.ledger.settle(CountIt.now());});t.waitTicks(3);t.takeScreenshot("r9-streak");t.waitTicks(85);t.runOnClient(c->{check(CountIt.ledger.streak(CountIt.now())==0,"Streak exceeded four seconds");Object message=field(c.inGameHud,"overlayMessage");check(message==null||((Text)message).getString().isEmpty(),"Streak actionbar did not clear");});t.setScreen(()->Visuals.editor(null));t.runOnClient(c->CountIt.test(2));t.waitTicks(8);t.takeScreenshot("r9-crowded-preview");t.runOnClient(c->{CountIt.stopTest();check(CountIt.demoCounts.isEmpty(),"Preview entities remained");});
   t.setScreen(()->DwmirLib.createScreen(null));t.getInput().setCursorPos(0,0);t.waitTicks(8);t.takeScreenshot("r9-library-six");
  }
  t.setScreen(()->null);System.out.println("DWMIR_R9_CHECKS_PASS OGG_DECODE=OK INLINE_PICKER=OK HUD_RESIZE=OK PERSISTENCE=OK NETWORK_POP=OK");
 }
}
